44	  static constexpr uint16_t kCsrFcsr     = 0x003;
45	  static constexpr uint16_t kCsrMstatus  = 0x300;
46	  static constexpr uint16_t kCsrMie      = 0x304;
47	  static constexpr uint16_t kCsrMtvec    = 0x305;
48	  static constexpr uint16_t kCsrMscratch = 0x340;
49	  static constexpr uint16_t kCsrMepc     = 0x341;
50	  static constexpr uint16_t kCsrMcause   = 0x342;
51	  static constexpr uint16_t kCsrMtval    = 0x343;
52	  static constexpr uint16_t kCsrMip      = 0x344;
53	  static constexpr uint16_t kCsrMcycle   = 0xB00;
54	  static constexpr uint16_t kCsrMinstret = 0xB02;
55	  // Andes machine setup CSRs crt0 writes at boot (see hybrid_state_v1):
56	  // mcache_ctl enables the L1 I/D caches, mmisc_ctl holds misc machine config.
57	  static constexpr uint16_t kCsrMcacheCtl = 0x7CA;
58	  static constexpr uint16_t kCsrMmiscCtl  = 0x7D0;
59	  static constexpr uint16_t kCsrVstart   = 0x008;
60	  static constexpr uint16_t kCsrVxsat    = 0x009;
61	  static constexpr uint16_t kCsrVxrm     = 0x00A;
62	  static constexpr uint16_t kCsrVcsr     = 0x00F;
63	  static constexpr uint16_t kCsrVtype    = 0xC21;
64	  static constexpr uint16_t kCsrVl       = 0xC20;
65	
66	  static constexpr uint32_t kDmcontrolDmactive  = 1u << 0;
67	  static constexpr uint32_t kDmcontrolResumereq = 1u << 30;
68	  static constexpr uint32_t kDmcontrolHaltreq   = 1u << 31;
69	
70	  static constexpr uint32_t kDmstatusAllhalted    = 1u << 9;
71	  static constexpr uint32_t kDmstatusAllresumeack = 1u << 17;
72	
73	  static constexpr uint32_t kAbstractcsBusy        = hybrid::kAbstractcsBusy;
74	  static constexpr uint32_t kAbstractcsCmderrMask  = hybrid::kAbstractcsCmderrMask;
75	
76	  // mstatus extension-state fields: FS (bits 14:13), VS (bits 10:9).
77	  // "Initial" (01) is the minimal enable the abstract FPR / V writes require.
78	  static constexpr uint64_t kMstatusFsMask    = 0x6000ULL;
79	  static constexpr uint64_t kMstatusFsInitial = 0x2000ULL;
80	  static constexpr uint64_t kMstatusVsMask    = 0x600ULL;
81	  static constexpr uint64_t kMstatusVsInitial = 0x200ULL;
82	
83	  static constexpr unsigned kPollIterations = kDmiPollIterations;
84	
85	  // scratch_gpa: the GUEST address of the V-register transport page (L26:
86	  // v_scratch_gpa(ram_base, ram_size) = the mmap's top page). Defaults to the
87	  // "unset" sentinel; a non-V resume never reads it, but a V resume with the
88	  // GPA still unset throws in the sweep (no silent transport via a bogus
89	  // address). The simulator passes the real value from platform.main_memory.
90	  // caps: which Andes custom CSRs the TARGET core implements (derived from its
91	  // config.inc, supplied by the sim binary). Defaults to all() -- transport
92	  // every CSR, the prior behavior -- so existing call sites are unchanged.
93	  explicit ResumeDriver(DmiBus& bus, uint64_t scratch_gpa = kVScratchGpaUnset,
94	                        AndesCaps caps = AndesCaps::all())
95	      : bus_{bus}, scratch_gpa_{scratch_gpa}, caps_{caps}
96	  {}
97	
98	  void resume(const hybrid_state_v1& state)
99	  {
100	    if (state.magic != HYBRID_STATE_MAGIC)
101	      throw std::runtime_error("ResumeDriver::resume: bad magic");
102	    if (state.version != HYBRID_STATE_VERSION)
103	      throw std::runtime_error("ResumeDriver::resume: unsupported version");
104	    // L6: only U(0)/S(1)/M(3) fit dcsr.prv; 2 is the reserved encoding.
105	    if (state.priv == 2 || state.priv > 3)
106	      throw std::runtime_error("ResumeDriver::resume: invalid privilege");
107	
108	    // dmactive must transition 0->1 in its own write before any other
109	    // DMCONTROL bit is honored (RISC-V Debug Spec).
110	    bus_.write(kDmcontrol, kDmcontrolDmactive);
111	    request_halt();
112	    poll_until_set(bus_, kDmstatus, kDmstatusAllhalted, "ResumeDriver halt");
113	
114	    // mstatus: enable FS / VS so the following FPR / V abstract writes are
115	    // accepted (FS or VS == Off disables the extension and the hart NACKs
116	    // the writes). The drained state.mstatus may legitimately carry FS or
117	    // VS at Off (e.g. an OS context-switched the regs away before the
118	    // trigger fired) -- gating the write on the drained field skips the
119	    // enable and silently NACKs every subsequent FPR / V-CSR write. Always
120	    // write mstatus when either extension is in scope; force-OR Initial
121	    // when the drained field is Off. This enable is local to the vsim
122	    // phase; the state.mstatus written to the handoff file is left
123	    // unmodified.
124	    if (state.flags & (HYBRID_FLAG_FP | HYBRID_FLAG_V)) {
125	      uint64_t enable_mstatus = state.mstatus;
126	      if ((state.flags & HYBRID_FLAG_FP) && (enable_mstatus & kMstatusFsMask) == 0)
127	        enable_mstatus |= kMstatusFsInitial;  // FS = Initial
128	      if ((state.flags & HYBRID_FLAG_V)  && (enable_mstatus & kMstatusVsMask) == 0)
129	        enable_mstatus |= kMstatusVsInitial;  // VS = Initial
130	      write_csr_abstract_or_pb(kCsrMstatus, enable_mstatus);
131	    }
132	
133	    // FPR restore (requires mstatus.FS enabled above): one abstract register
134	    // write per f-reg. Abstract-only by design, like every non-V register
135	    // block -- the Program Buffer is reserved for state the abstract command
136	    // space cannot reach (the V regfile, vtype/vl).
137	    if (state.flags & HYBRID_FLAG_FP) {
138	      for (uint16_t i = 0; i < 32; ++i)
139	        write_64bit_register(regno_fpr(i), state.fpr[i]);
140	      // L20: fcsr (frm + sticky fflags). Same FS gate as the FPRs; PB
141	      // fallback scratch x5 is overwritten by the GPR loop below.
142	      write_csr_abstract_or_pb(kCsrFcsr, state.fcsr);
143	    }
144	
145	    // Tier-A V CSR restore (before GPRs: PB fallback uses x5 as scratch;
146	    // the GPR loop overwrites x5 afterward so state is preserved).
147	    if (state.flags & HYBRID_FLAG_V) {
148	      // V data regfile: reload v0..v31 from the shared scratch region via the
149	      // Program Buffer. Runs BEFORE the architectural V-CSR restore below
150	      // because the sweep's own vsetvl (e8/m8) clobbers vtype/vl/vstart, which
151	      // the restore then overwrites with the architectural values. The sweep
152	      // uses x5/x6/x7 as scratch (x7 is the group base pointer); the GPR loop
153	      // below restores all three. The scratch is vlenb-packed
154	      // (stage_v_to_scratch), so the sweep takes only the runtime vlenb.
155	      if (scratch_gpa_ == kVScratchGpaUnset)
156	        throw std::runtime_error(
157	          "ResumeDriver::resume: V state present but scratch GPA unset");
158	      pb_v_data_sweep(bus_, scratch_gpa_, state.vlenb, /*load=*/true);
159	
160	      // Tier-B: vtype+vl via vsetvl x0,x5,x6 in PB.
161	      // Direct csrrw to vtype sets vill; vl is read-only. Stage operands in
162	      // scratch GPRs x5(vl) and x6(vtype) then let vsetvl set both atomically.
163	      // x5/x6 are overwritten by the GPR loop below, so no leakage.
164	      write_64bit_register(regno_gpr(5), state.vl);
165	      write_64bit_register(regno_gpr(6), state.vtype);
166	      const std::array<uint32_t, 1> pb_vsetvl = { encode_vsetvl(0, 5, 6) };
167	      exec_progbuf(bus_, std::span<const uint32_t>{pb_vsetvl});
168	
169	      // vstart must come AFTER vsetvl: vsetvl resets vstart to 0.
170	      write_csr_abstract_or_pb(kCsrVstart, state.vstart);
171	      write_csr_abstract_or_pb(kCsrVxsat,  state.vxsat);
172	      write_csr_abstract_or_pb(kCsrVxrm,   state.vxrm);
173	      write_csr_abstract_or_pb(kCsrVcsr,   state.vcsr);
174	    }
175	
176	    // L6: dret resumes into dcsr.prv, which is M after the boot halt. For an
177	    // S/U-mode handoff, read-modify-write the prv field so the ROI executes
178	    // in the drained privilege; M-mode states skip the write (prv already 3).
179	    // Before the GPR loop: a PB fallback would clobber scratch x5.
180	    if (state.priv != 3) {
181	      // L2 slice: with PMP implemented and no matching entry, every S/U
182	      // access faults (priv spec v1.10) -- mirror the producer's PMP block
183	      // so the ROI can fetch at all. All pmpaddr before any pmpcfg (a locked
184	      // cfg discards later addr writes); odd pmpcfg CSRs do not exist on
185	      // RV64. Tolerant writes: entries beyond what the hart implements
186	      // mirror as no-ops. M-mode handoffs keep PMP pass-through-only (L2).
187	      for (uint16_t i = 0; i < HYBRID_PMP_ADDR_NUM; ++i)
188	        write_csr_tolerant(kCsrPmpaddr0 + i, state.pmpaddr[i]);
189	      for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; i += 2)
190	        write_csr_tolerant(kCsrPmpcfg0 + i, state.pmpcfg[i]);
191	
192	      const uint64_t dcsr =
193	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr");
194	      write_csr_abstract_or_pb(kCsrDcsr,
195	                               (dcsr & ~uint64_t{0x3}) | state.priv);
196	      // An M-only core WARL-pins dcsr.prv to 3; resuming anyway would
197	      // silently measure the ROI in the wrong privilege. Verify and abort.
198	      const uint64_t got =
199	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr verify")
200	        & 0x3u;
201	      if (got != state.priv)
202	        throw std::runtime_error(
203	          "ResumeDriver::resume: engine does not implement privilege level "
204	          + std::to_string(state.priv)
205	          + " (dcsr.prv pinned to " + std::to_string(got)
206	          + "); pick an S/U-capable engine");
207	    }
208	
209	    // Andes V5 + M-ext CSR restore (abstract-only). See restore_andes_m_ext.
210	    restore_andes_m_ext(state);
211	
212	    // GPRs + DPC (after V CSRs so PB scratch x5 is safe to overwrite): one
213	    // abstract register write per GPR.
214	    for (uint16_t i = 1; i < 32; ++i)
215	      write_64bit_register(regno_gpr(i), state.gpr[i]);
216	    write_64bit_register(regno_csr(kCsrDpc), state.pc);
217	
218	    write_csr_tolerant(kCsrMtvec, state.mtvec);
219	
220	    // L23: mscratch is the M-mode software scratch CSR -- a pure read/write
221	    // register with no hardware side effects, legal to use inside a trap-free
222	    // ROI. Restore it so a value stashed before the handoff survives into the
223	    // vsim phase.
224	    write_csr_tolerant(kCsrMscratch, state.mscratch);
225	
226	    // L24: the writable M-mode trap/interrupt CSRs. In the trap-free,
227	    // interrupt-free ROI envelope these are ordinary read/write registers, so a
228	    // value stashed before the handoff must survive into the vsim phase (same
229	    // round-trip as mscratch). Tolerant writes: a WARL / read-only field (mip's
230	    // hardware-driven pending bits, or mtval on a core that hardwires it)
231	    // mirrors as a no-op. medeleg/mideleg/satp stay unrestored -- they are
232	    // S-mode CSRs the M-only default engine does not implement (L3/L4).
233	    write_csr_tolerant(kCsrMepc,   state.mepc);
234	    write_csr_tolerant(kCsrMcause, state.mcause);
235	    write_csr_tolerant(kCsrMtval,  state.mtval);
236	    write_csr_tolerant(kCsrMie,    state.mie);
237	    write_csr_tolerant(kCsrMip,    state.mip);
238	
239	    // Andes cache fix: restore the machine setup CSRs crt0 wrote at boot. The
240	    // functional engine ran crt0 (where `csrw mcache_ctl` enables the L1 I/D
241	    // caches) but has no cache model, so without this the cycle engine resumes
242	    // at the ROI with caches at their reset default -- DISABLED -- and the
243	    // whole measured window runs uncached, inflating it severalfold. Tolerant
244	    // writes: an engine without these custom CSRs (e.g. non-Andes) mirrors the
245	    // write as a no-op, and a drained 0 (caches were off) restores the reset
246	    // state, so this is always safe to issue.
247	    write_csr_tolerant(kCsrMcacheCtl, state.mcache_ctl);
248	    write_csr_tolerant(kCsrMmiscCtl,  state.mmisc_ctl);
249	
250	    // F-T2.4: restore mcycle/minstret so the vsim phase continues counting
251	    // from QEMU1's drain value. Without this, vsim's local counter starts
252	    // at zero, so the drained mcycle delta (vsim minus QEMU 1) would no
253	    // longer measure the ROI. PB fallback uses x5 as scratch; safe to
254	    // overwrite here as the GPR loop already ran.
255	    write_csr_abstract_or_pb(kCsrMcycle,   state.mcycle);
256	    write_csr_abstract_or_pb(kCsrMinstret, state.minstret);
257	
258	    clear_cmderr_if_set();
259	    request_resume();
260	    poll_until_set(bus_, kDmstatus, kDmstatusAllresumeack,
261	                   "ResumeDriver resume");
262	  }
263	
264	private:
265	  void request_halt()
266	  {
267	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolHaltreq);
268	  }
269	
270	  void request_resume()
271	  {
272	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolResumereq);
273	  }
274	
275	  void write_64bit_register(uint16_t regno, uint64_t value)
276	  {
277	    write_register_abstract(bus_, regno, value);
278	  }
279	
280	  // Andes V5 + M-ext CSR restore: one caps-gated abstract write per CSR
281	  // (pmaaddr before pmacfg, mirroring the PMP restore ordering). Abstract-only
282	  // by design -- a batched Program-Buffer sweep can't tolerate a cmderr on one
283	  // CSR without corrupting the rest of the batch (a WARL/read-only CSR faults
284	  // the whole group mid-sweep), whereas the per-CSR abstract path tolerates a
285	  // single failure and moves on.
286	  void restore_andes_m_ext(const hybrid_state_v1& state)
287	  {
288	    const bool andes = state.flags & HYBRID_FLAG_ANDES;
289	    const bool mext  = state.flags & HYBRID_FLAG_M_EXT;
290	    if (!andes && !mext) return;
291	
292	    if (andes) {
293	#define X(field, addr, name) \
294	  if (caps_.supports_csr(addr)) write_csr_tolerant(addr, state.andes.field);
295	      HYBRID_ANDES_CSR_LIST(X)
296	#undef X
297	      for (uint16_t i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
298	        if (caps_.supports_csr(HYBRID_PMA_ADDR0_CSR + i))
299	          write_csr_tolerant(HYBRID_PMA_ADDR0_CSR + i, state.andes.pmaaddr[i]);
300	      for (uint16_t i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
301	        if (caps_.supports_csr(HYBRID_PMA_CFG0_CSR + 2 * i))
302	          write_csr_tolerant(HYBRID_PMA_CFG0_CSR + 2 * i, state.andes.pmacfg[i]);
303	    }
304	    if (mext) {
305	#define X(field, addr, name) \
306	  if (caps_.supports_csr(addr)) write_csr_tolerant(addr, state.m_ext.field);
307	      HYBRID_M_EXT_CSR_LIST(X)
308	#undef X
309	    }
310	  }
311	
312	  // Abstract-first CSR write with Program Buffer fallback.
313	  // Tries an abstract register write; if the DM signals cmderr, clears it,
314	  // stages the value in scratch_gpr via abstract GPR write, then executes a
315	  // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
316	  // to x5 (t0) which the GPR restore loop overwrites later.
317	  void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
318	                                 uint8_t scratch_gpr = 5)
319	  {
320	    write_64bit_register(regno_csr(csr), value);
321	    if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
322	    bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
323	    write_64bit_register(regno_gpr(scratch_gpr), value);
324	    const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
325	    exec_progbuf(bus_, std::span<const uint32_t>{pb});
326	  }
327	
328	  // Write a CSR-addressable register and clear any cmderr the DM raised.
329	  // Used for CSRs whose abstract-access support may be implementation
330	  // dependent; a missing CSR mirrors as a no-op rather than blocking the
331	  // remaining writes.
332	  void write_csr_tolerant(uint16_t csr, uint64_t value)
333	  {
334	    write_64bit_register(regno_csr(csr), value);
335	    clear_cmderr_if_set();
336	  }
337	
338	  // abstractcs.cmderr is sticky per the Debug Spec - a subsequent command
339	  // is rejected until the bits are W1C-cleared. We tolerate per-register
340	  // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
341	  // error before resuming so the hart isn't left in a stuck state.
342	  // B17: record the last observed non-zero cmderr and a clear count so a
343	  // partially-broken restore is observable via the public accessors
344	  // instead of silently swallowed.
345	  void clear_cmderr_if_set()
346	  {
347	    const auto status = bus_.read(kAbstractcs);
348	    const auto code = (status & kAbstractcsCmderrMask) >> 8;
349	    if (code != 0u) {
350	      last_observed_cmderr_ = code;
351	      ++cmderr_clear_count_;
352	      bus_.write(kAbstractcs, kAbstractcsCmderrMask);
353	    }
354	  }
355	
356	  DmiBus& bus_;
357	  uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
358	  AndesCaps caps_ = AndesCaps::all();         // target core's Andes-CSR support
359	  uint32_t last_observed_cmderr_ = 0;
360	  uint64_t cmderr_clear_count_   = 0;
361	
362	public:
363	  // B17: diagnostic side channel. Non-zero last_observed_cmderr() means
364	  // at least one abstract write tripped a sticky cmderr the restore
365	  // tolerated by clearing. cmderr_clear_count() is the total number of
366	  // such clears across all calls into clear_cmderr_if_set() this run.
367	  auto last_observed_cmderr() const -> uint32_t { return last_observed_cmderr_; }
368	  auto cmderr_clear_count() const -> uint64_t   { return cmderr_clear_count_; }
369	};
370	
371	// Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
372	// via an Abstract Command. Halts-and-reads contract: caller must have the
373	// hart in the halted state. Shared by StateDrain (drain at exit). If
374	// abstractcs.cmderr goes sticky after the command, the helper clears it and
375	// reports 0 rather than blocking the caller -- a missing CSR mirrors as zero
376	// instead of corrupting the adjacent field.
377	inline auto read_register_64_checked(DmiBus& bus, uint16_t regno,
378	                                     const char* poll_label
379	                                       = "read_register_64")
380	  -> std::optional<uint64_t>
381	{
382	  using RD = ResumeDriver;
383	  bus.write(RD::kCommand,
384	            access_register_command(regno, AarSize::Bits64, /*write=*/false));
385	  poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
386	  const auto status = bus.read(RD::kAbstractcs);
387	  if ((status & RD::kAbstractcsCmderrMask) != 0u) {
388	    bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
389	    return std::nullopt;
390	  }
391	  const uint64_t lo = bus.read(RD::kData0);
392	  const uint64_t hi = bus.read(RD::kData1);
393	  return lo | (hi << 32);
394	}
395	
396	inline auto read_register_64(DmiBus& bus, uint16_t regno,
397	                             const char* poll_label = "read_register_64")
398	  -> uint64_t
399	{
400	  return read_register_64_checked(bus, regno, poll_label).value_or(0u);
401	}
402	
403	}  // namespace hybrid
