  // Andes V5 + M-ext CSR restore: one caps-gated abstract write per CSR
  // (pmaaddr before pmacfg, mirroring the PMP restore ordering). Abstract-only
  // by design -- a batched Program-Buffer sweep can't tolerate a cmderr on one
  // CSR without corrupting the rest of the batch (a WARL/read-only CSR faults
  // the whole group mid-sweep), whereas the per-CSR abstract path tolerates a
  // single failure and moves on.
  void restore_andes_m_ext(const hybrid_state_v1& state)
  {
    const bool andes = state.flags & HYBRID_FLAG_ANDES;
    const bool mext  = state.flags & HYBRID_FLAG_M_EXT;
    if (!andes && !mext) return;

    if (andes) {
#define X(field, addr, name) \
  if (caps_.supports_csr(addr)) write_csr_tolerant(addr, state.andes.field);
      HYBRID_ANDES_CSR_LIST(X)
#undef X
      for (uint16_t i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
        if (caps_.supports_csr(HYBRID_PMA_ADDR0_CSR + i))
          write_csr_tolerant(HYBRID_PMA_ADDR0_CSR + i, state.andes.pmaaddr[i]);
      for (uint16_t i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
        if (caps_.supports_csr(HYBRID_PMA_CFG0_CSR + 2 * i))
          write_csr_tolerant(HYBRID_PMA_CFG0_CSR + 2 * i, state.andes.pmacfg[i]);
    }
    if (mext) {
#define X(field, addr, name) \
  if (caps_.supports_csr(addr)) write_csr_tolerant(addr, state.m_ext.field);
      HYBRID_M_EXT_CSR_LIST(X)
#undef X
    }
  }

